import { hbs } from 'ember-cli-htmlbars';

const SkinTypes = ['primary', 'secondary'];
const SizeTypes = ['xs', 'sm', 'md', 'lg'];

export default {
  title: 'Components/OSS::Smart::Button',
  component: 'button',
  argTypes: {
    skin: {
      description: 'Adjust appearance',
      table: {
        type: {
          summary: SkinTypes.join('|')
        },
        defaultValue: { summary: 'primary' }
      },
      options: SkinTypes,
      control: { type: 'select' }
    },
    size: {
      description: 'Adjust size',
      table: {
        type: {
          summary: SizeTypes.join('|')
        },
        defaultValue: { summary: 'null' }
      },
      options: SizeTypes,
      control: { type: 'select' }
    },
    loading: {
      description: 'Display loading state',
      table: {
        type: {
          summary: 'boolean'
        },
        defaultValue: { summary: 'false' }
      },
      control: { type: 'boolean' }
    },
    loadingOptions: {
      description: 'Options to configure the loading state',
      table: {
        type: {
          summary: '{ showLabel?: boolean }'
        },
        defaultValue: { summary: 'undefined' }
      },
      control: { type: 'object' }
    },
    label: {
      description: 'Text content of the button',
      table: {
        type: { summary: 'string' },
        defaultValue: { summary: 'undefined' }
      },
      control: {
        type: 'text'
      }
    },
    icon: {
      description: 'Font Awesome class, for example: far fa-envelope-open',
      table: {
        type: { summary: 'string' },
        defaultValue: { summary: 'undefined' }
      },
      control: {
        type: 'text'
      }
    },
    iconUrl: {
      description: 'Url of an icon that will be shown within the button',
      table: {
        type: { summary: 'string' },
        defaultValue: { summary: 'undefined' }
      },
      control: {
        type: 'text'
      }
    },
    circle: {
      description: 'Displays the button as a circle. Useful for icon buttons.',
      table: {
        type: { summary: 'boolean' },
        defaultValue: { summary: 'false' }
      },
      control: {
        type: 'boolean'
      }
    },
    disabled: {
      description: 'Disables the button',
      table: {
        type: {
          summary: 'boolean'
        },
        defaultValue: { summary: false }
      },
      control: { type: 'boolean' }
    }
  },
  parameters: {
    docs: {
      description: {
        component: 'The smart version of the button component. Configurable & skinable.'
      }
    },
    design: {
      type: 'figma',
      url: 'https://www.figma.com/file/N7SDuH9mvC9zTlsLN49N4L/2.0-UI-Kit-%F0%9F%92%A0?node-id=1102-266&p=f&t=pVIlyZlo6oyvIQxs-0'
    }
  }
};

const defaultArgs = {
  skin: 'primary',
  size: 'md',
  loading: false,
  label: 'Label',
  icon: 'far fa-envelope-open',
  circle: false,
  loadingOptions: undefined,
  iconUrl: undefined,
  disabled: false
};

const Template = (args) => ({
  template: hbs`
    <OSS::Smart::Button
      @skin={{this.skin}} @size={{this.size}} @loading={{this.loading}} @label={{this.label}} @icon={{this.icon}}
      @circle={{this.circle}} @iconUrl={{this.iconUrl}} @loadingOptions={{this.loadingOptions}} @disabled={{this.disabled}} />
  `,
  context: args
});

export const Default = Template.bind({});
Default.args = defaultArgs;

export const WithIconUrl = Template.bind({});
WithIconUrl.args = {
  ...defaultArgs,
  ...{
    icon: undefined,
    iconUrl: '/@upfluence/oss-components/assets/images/no-image.svg'
  }
};
